import { Button, Col, Modal, Popconfirm, Row } from 'antd'
import get from 'lodash/get'
import { useCallback, useEffect, useMemo, useState } from 'react'
import LayoutContentStyle from '../../../../../../../../components/utility/layoutContent.style'
import PropTypes from 'prop-types'
import moment from 'moment-timezone'
import Cookies from 'universal-cookie'
import ReconForm from '../../../../components/ReconForm'
import { ReconInfoStyle } from './index.style'
import { openDocInNewTabFromUrl } from '../../../../../../../../helpers/utility'
import { useAddRecon } from '../../../../state/hooks/useReconState'
import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { showNotification } from '../../../../../../../../components/ShowNotification'

const cookies = new Cookies()

function ReconInfo (props) {
  const userTimeZone = useMemo(() => {
    return cookies.get('userProfile').user_timezone
  }, [])

  const [, addReconRequest] = useAddRecon()

  const [showReconForm, setShowReconForm] = useState(false)
  const { reconInfo, onGetReconDetail } = props
  const renderInfo = useCallback(() => {
    const data = [
      {
        key: 'File Name',
        value: get(reconInfo, 'file_name', '')
      },
      {
        key: 'Provider Name',
        value: get(reconInfo, 'provider', '')
      },
      {
        key: 'Recon Purpose',
        value: get(reconInfo, 'recon_purpose', '')
      },
      {
        key: 'Recon Type',
        value: get(reconInfo, 'recon_type', '')
      },
      {
        key: 'Recon To',
        value: get(reconInfo, 'recon_to', '')
      },
      {
        key: 'Payment Date',
        value: moment(get(reconInfo, 'payment_date', '')).tz(userTimeZone).format('DD-MM-YYYY')
      },
      {
        key: 'Status',
        value: get(reconInfo, 'status', '')
      },
      ...(
        get(reconInfo, 'error', '')
          ? [{
              key: 'Error',
              value: get(reconInfo, 'error', '')
            }]
          : []
      ),
      {
        key: 'Invoice',
        value: get(reconInfo, 'invoice_url', '')
      },
      {
        key: 'Payment Proof',
        value: get(reconInfo, 'payment_proof_url', '')
      },
      {
        key: 'Total Payment',
        value: get(reconInfo, 'amount', '')
      },
      {
        key: 'Remark',
        value: get(reconInfo, 'remarks', '')
      },
      {
        key: 'Uploaded At',
        value: moment(get(reconInfo, 'created_at', '')).tz(userTimeZone).format('DD-MM-YYYY')
      },
      {
        key: 'Created By',
        value: get(reconInfo, 'created_by', '')
      },
      {
        key: 'Edited By',
        value: get(reconInfo, 'updated_by', '')
      },
      {
        key: 'Edited At',
        value: moment(get(reconInfo, 'updated_at', '')).tz(userTimeZone).format('DD-MM-YYYY')
      }
    ]

    return (
      <>
        {
          data.map((row, i) => (
            <Row type='flex' key={i}>
              <Col span={8}>
                <b>{row.key}</b>
              </Col>
              <Col span={14}>
                {
                  ['Invoice', 'Payment Proof'].includes(row.key) ? <a href={row.value} rel='noreferrer' target='_blank'>{row.value}</a> : row.value
                }
              </Col>
            </Row>
          ))
        }
      </>
    )
  }, [reconInfo, userTimeZone])

  const [{ ADD_RECON_ERROR, addReconStatus }, dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (addReconStatus === 'success') {
      showNotification('success', 'Recon Confirmed')
      dispatchError(resetError({
        addReconStatus: ''
      }))
      onGetReconDetail({
        reconId: reconInfo.id
      })
    } else if (ADD_RECON_ERROR && addReconStatus) {
      showNotification('error', addReconStatus)
      dispatchError(resetError({
        addReconStatus: ''
      }))
    }
  }, [addReconStatus, dispatchError,
    ADD_RECON_ERROR, reconInfo, onGetReconDetail
  ])

  const closeReconForm = useCallback(() => {
    setShowReconForm(false)
  }, [])

  const handleEditRecon = useCallback(() => {
    setShowReconForm(true)
  }, [])

  const handleDownloadReconFile = useCallback(() => {
    openDocInNewTabFromUrl(reconInfo.file_url)
  }, [reconInfo])

  const handleConfirmRecon = useCallback(() => {
    addReconRequest({
      reconId: reconInfo?.id,
      body: {
        recon_status: 'COMPLETED'
      }
    })
  }, [reconInfo, addReconRequest])

  const isHideConfirmBtn = reconInfo?.recon_status === 'COMPLETED' || reconInfo?.status === 'FAILED'
  const isHideEditBtn = reconInfo?.recon_status === 'COMPLETED'

  return (
    <ReconInfoStyle>
      <LayoutContentStyle>
        {
          showReconForm &&
            <Modal
              style={{ top: '0' }}
              footer={null}
              visible={showReconForm}
              onCancel={closeReconForm}
            >
              <ReconForm onGetReconDetail={onGetReconDetail} defaultValues={reconInfo} onCloseReconForm={closeReconForm} />
            </Modal>
        }
        <Row type='flex' justify='space-between'>
          <Col>
            <h3 className='heading-blue'><b>File Details</b></h3>
          </Col>
          <Col>
            <Button
              className='ml-10 mb-10'
              type='primary'
              htmlType='submit'
              onClick={handleDownloadReconFile}
            >
              Download Original File
            </Button>
            <>
              {
                  !isHideConfirmBtn &&
                    <Popconfirm
                      title={
                        <div>
                          Are you sure to confirm the recon data uploaded is correct?
                          <p><i>All the policies in the excel file will remark the recon status is done. Please recheck and make sure all the data uploaded is correct!</i></p>
                        </div>
                    }
                      onConfirm={handleConfirmRecon}
                      okText='Yes'
                      cancelText='No'
                    >
                      <Button
                        className='ml-10 mb-10 btn-green'
                        htmlType='submit'
                      >
                        Confirm
                      </Button>
                    </Popconfirm>
                }
              {
                  !isHideEditBtn &&
                    <Button
                      className='ml-10 mb-10 btn-grey'
                      htmlType='submit'
                      onClick={handleEditRecon}
                    >
                      Edit Recon Data
                    </Button>
                }
            </>
          </Col>
        </Row>

        <div className='mt-10'>
          {
            renderInfo()
          }
        </div>
      </LayoutContentStyle>
    </ReconInfoStyle>
  )
}

ReconInfo.propTypes = {
  reconInfo: PropTypes.object,
  onGetReconDetail: PropTypes.func
}

export default ReconInfo
