import CircularLoader from '../../../../../../../components/CircularLoader'
import { ReconDetailStyle } from './index.style'
import { Button, Row } from 'antd'
import { useCallback, useEffect, useMemo, useState } from 'react'
import ReconInfo from '../components/ReconInfo'
import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useGetPolicyList, useGetReconDetail } from '../../../state/hooks/useReconState'
import { showNotification } from '../../../../../../../components/ShowNotification'
import TableWrapper from '../../../../pagination.style'
import { policyListTable } from '../../../constants'
import { openDocInNewTabFromUrl } from '../../../../../../../helpers/utility'

function ReconDetail (props) {
  const [{ getPolicyListData = {} }, getPolicyListRequest] = useGetPolicyList()
  const [{ getReconDetailData = {} }, getReconDetailRequest] = useGetReconDetail()
  const [policyColumns, setPolicyColumns] = useState([])
  const { reconId } = useMemo(() => props.match.params, [props.match.params])
  const [{ GET_POLICY_LIST_LOADER, GET_RECON_DETAIL_LOADER }
  ] = useLoaderContextValue()

  const [{ GET_POLICY_LIST_ERROR, GET_RECON_DETAIL_ERROR, getPolicyListStatus, getReconDetailStatus },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (getPolicyListStatus && GET_POLICY_LIST_ERROR) {
      showNotification('error', getPolicyListStatus)
      dispatchError(resetError({
        getPolicyListStatus: ''
      }))
    }
    if (getReconDetailStatus && GET_RECON_DETAIL_ERROR) {
      showNotification('error', getReconDetailStatus)
      dispatchError(resetError({
        getReconDetailStatus: ''
      }))
    }
  }, [getPolicyListStatus, getReconDetailStatus,
    GET_POLICY_LIST_ERROR, GET_RECON_DETAIL_ERROR,
    dispatchError
  ])

  useEffect(() => {
    getPolicyListRequest({
      reconId
    })
    getReconDetailRequest({
      reconId
    })
  }, [reconId, getPolicyListRequest,
    getReconDetailRequest
  ])

  const getPolicyListTable = useCallback(() => {
    return policyListTable()
  }, [])

  useEffect(() => {
    setPolicyColumns(getPolicyListTable())
  }, [getPolicyListTable])

  const handleGoBack = useCallback(() => {
    props.history.goBack()
  }, [props.history])

  const handleDownloadReconFile = useCallback(() => {
    openDocInNewTabFromUrl(getReconDetailData?.updated_file_url)
  }, [getReconDetailData])

  return (
    <ReconDetailStyle>
      <CircularLoader isSpining={GET_POLICY_LIST_LOADER || GET_RECON_DETAIL_LOADER}>
        <Button
          className='mb-10'
          type='primary'
          htmlType='submit'
          onClick={handleGoBack}
        >
          Back
        </Button>
        <ReconInfo reconInfo={getReconDetailData} onGetReconDetail={getReconDetailRequest} />
        <div className='mt-10'>
          {
            getReconDetailData?.updated_file_url &&
              <Row type='flex' justify='end'>
                <Button
                  className='ml-10 mb-10'
                  type='primary'
                  htmlType='submit'
                  onClick={handleDownloadReconFile}
                >
                  Download Updated File
                </Button>
              </Row>
          }
          <TableWrapper
            columns={policyColumns}
            bordered
            rowKey={record => record.id}
            dataSource={getPolicyListData?.data?.length > 0 ? getPolicyListData?.data : []}
            pagination={{
              pageSize: 10
            }}
            className='isoSearchableTable agent-table-data'
          />
        </div>
      </CircularLoader>
    </ReconDetailStyle>
  )
}

export default ReconDetail
